For the sandbox timeout during long-running commands:

Add configurable timeout with auto-renewal for commands that produce output:

```python
async def run_with_renewable_timeout(self, cmd, timeout=300):
    proc = await asyncio.create_subprocess_shell(
        cmd, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE
    )
    deadline = time.time() + timeout
    while True:
        try:
            line = await asyncio.wait_for(
                proc.stdout.readline(), timeout=max(0, deadline - time.time())
            )
            if line:
                deadline = time.time() + timeout  # Renew on output
            else:
                break
        except asyncio.TimeoutError:
            proc.kill()
            return {'status': 'timeout', 'output': buffer}
    return {'status': 'completed', 'output': buffer}
```

